interface ProductRepositoryPort {
    String findNameById(long id);
}

class SlowProductRepositoryAdapter implements ProductRepositoryPort {
    public String findNameById(long id) {
        System.out.println("Wolny dostep do danych dla id=" + id); // symulacja np. sieci/dysku
        return "Produkt-" + id;
    }
}

class CachedProductRepositoryAdapter implements ProductRepositoryPort {
    private final ProductRepositoryPort delegate;
    private final Map<Long, String> cache = new HashMap<>();

    CachedProductRepositoryAdapter(ProductRepositoryPort delegate) { this.delegate = delegate; }

    public String findNameById(long id) {
        if (cache.containsKey(id)) return cache.get(id); // trafienie w cache
        String result = delegate.findNameById(id);        // "cache miss" - pytamy prawdziwe zrodlo
        cache.put(id, result);
        return result;
    }
}

class CachedProductRepositoryAdapterWithInvalidation extends CachedProductRepositoryAdapter {
    // ... (konstruktor jak wyzej)
    void invalidate(long id) {
        cache.remove(id); // WYMAGANE po kazdej zmianie danego produktu w prawdziwym zrodle
    }
}

