// ZLE: cache i logika biznesowa wymieszane w 1 metodzie
class DiscountServiceWithInlineCache {
    private final Map<String, Double> discountCache = new HashMap<>();

    double calculateDiscount(String customerId) {
        if (discountCache.containsKey(customerId)) return discountCache.get(customerId);
        double discount = customerId.startsWith("VIP") ? 0.2 : 0.05; // logika biznesowa
        discountCache.put(customerId, discount); // logika cache'owania - ZMIESZANA z biznesowa
        return discount;
    }
}

// DOBRZE: Service zawiera TYLKO logike biznesowa, bez sladu cache'owania
interface DiscountPort { double calculateDiscount(String customerId); }

class DiscountService implements DiscountPort {
    public double calculateDiscount(String customerId) {
        return customerId.startsWith("VIP") ? 0.2 : 0.05; // WYLACZNIE logika biznesowa
    }
}

class CachedDiscountDecorator implements DiscountPort {
    private final DiscountPort delegate;
    private final Map<String, Double> cache = new HashMap<>();
    CachedDiscountDecorator(DiscountPort delegate) { this.delegate = delegate; }

    public double calculateDiscount(String customerId) {
        return cache.computeIfAbsent(customerId, delegate::calculateDiscount);
    }
}
